22	// A Helm chart or a Kustomize overlay is validated after it is rendered
23	// (§3.80). Both renderers are optional: without them the directory is
24	// reported as not rendered, never as clean, and never as a missing tool —
25	// the schema stage did all it could.
26	//
27	// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
28	// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
29	// alpine/helm's entrypoint is `helm`, the kustomize image's is
30	// /app/kustomize, so in both the arguments follow the image name.
31	
32	// Default images for the two renderers.
33	const (
34		DefaultHelmImage      = "alpine/helm"
35		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
36	)
37	
38	// remoteBlockedHeadline is the title of a K8S-RENDER finding whose remote base the
39	// cut network refused. It replaces the generic one, which would end with
40	// kustomize's own first line: the message keeps the whole text.
41	const remoteBlockedHeadline = "Overlay does not build: remote base blocked"
42	
43	// IDs of the findings the renderers themselves produce.
44	const (
45		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
46		HelmLintID = "HELM-LINT"
47		// K8sRenderID is a chart or an overlay that did not render at all.
48		K8sRenderID = "K8S-RENDER"
49	)
50	
51	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
52	// support.Message.Error formats it.
53	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
54	
55	// helmSourceLine is the comment helm template writes above each document,
56	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
57	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
58	
59	// renderScope is where a renderer runs. A binary runs in the target and sees
60	// the whole host. A container sees only mount, read-only at /scan, and works in
61	// the target inside it: mount is the target itself, or the git repository
62	// holding it, so an overlay or a chart can reach a sibling of the target as it
63	// does on the host (DEVDESK-742).
64	type renderScope struct {
65		target string
66		mount  string
67		// rel is the target relative to mount, with forward slashes; "" when the
68		// target is what is mounted.
69		rel string
70		// offline runs the renderer with the network cut (DEVDESK-767): a binary
71		// gets offlineEnviron, an image `--network none` and no proxy.
72		offline bool
73	}
74	
75	// cut is the scope with the network cut for the renderer that runs in it.
76	func (s renderScope) cut() renderScope {
77		s.offline = true
78		return s
79	}
80	
81	// targetOnly mounts the target and nothing else.
82	func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }
83	
84	// workdir is the target inside the container.
85	func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }
86	
87	// userHomeDir is the home directory the mount guard keeps out of reach. Tests
88	// swap it.
89	var userHomeDir = os.UserHomeDir
90	
91	// resolveRenderScope asks git, in the target, for the repository holding it.
92	// Without an answer (no git, not a repository), or when the repository's
93	// configuration moves its work tree elsewhere (core.worktree, which a cloned
94	// .git file can bring along), the target alone is mounted.
95	func resolveRenderScope(ctx context.Context, target string) renderScope {
96		git := func(args ...string) ([]byte, error) {
97			return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
98		}
99		out, err := git("rev-parse", "--show-toplevel")
100		if err != nil {
101			log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
102			return targetOnly(target)
103		}
104		worktree, err := git("config", "--get", "core.worktree")
105		var exitErr *exitError
106		unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
107		if !unset {
108			log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
109				target, strings.TrimSpace(string(worktree)), err)
110			return targetOnly(target)
111		}
112		scope, ok := widerScope(target, strings.TrimSpace(string(out)))
113		if !ok {
114			return targetOnly(target)
115		}
116		log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
117		return scope
118	}
119	
120	// gitEnviron is env without the variables that point git at another
121	// repository, work tree or configuration: the mount is decided by the target
122	// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
123	// repository earlier, and dropping it would widen what the user limited.
124	func gitEnviron(env []string) []string {
125		out := make([]string, 0, len(env))
126		for _, kv := range env {
127			name, _, _ := strings.Cut(kv, "=")
128			switch {
129			case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
130				strings.HasPrefix(name, "GIT_CONFIG"):
131				continue
132			}
133			out = append(out, kv)
134		}
135		return out
136	}
137	
138	// widerScope mounts top, the repository git named, when it is safe to: top is
139	// a strict ancestor of the target once symlinks are resolved, neither the
140	// filesystem root nor the home directory nor anything above it, and it holds
141	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
142	// included, keeps the target alone.
143	func widerScope(target, top string) (renderScope, bool) {
144		if top == "" || !filepath.IsAbs(top) {
145			return renderScope{}, false
146		}
147		root, err := filepath.EvalSymlinks(top)
148		if err != nil {
149			return renderScope{}, false
150		}
151		real, err := filepath.EvalSymlinks(target)
152		if err != nil {
153			return renderScope{}, false
154		}
155		rel, err := filepath.Rel(root, real)
156		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
157			return renderScope{}, false
158		}
159		if filepath.Dir(root) == root {
160			return renderScope{}, false
161		}
162		home, err := userHomeDir()
163		if err != nil || home == "" {
164			return renderScope{}, false
165		}
166		if h, err := filepath.EvalSymlinks(home); err == nil {
167			home = h
168		}
169		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
170			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
171			return renderScope{}, false
172		}
173		if !gitDirIsHere(root) {
174			return renderScope{}, false
175		}
176		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
177	}
178	
179	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
180	// one line, a path.
181	const maxGitFile = 4096
182	
183	// gitDirIsHere reports whether root holds its repository's .git: a directory,
184	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
185	// root's .git back in its own gitdir file. A symlink, a file that says
186	// anything else, or a git directory that does not point back is refused: git
187	// was then told where the work tree is, rather than finding it.
188	func gitDirIsHere(root string) bool {
189		dotGit := filepath.Join(root, ".git")
190		info, err := os.Lstat(dotGit)
191		if err != nil {
192			return false
193		}
194		if info.IsDir() {
195			return true
196		}
197		if !info.Mode().IsRegular() {
198			return false
199		}
200		line, ok := readGitFile(dotGit)
201		gitDir, found := strings.CutPrefix(line, "gitdir: ")
202		if !ok || !found {
203			return false
204		}
205		if !filepath.IsAbs(gitDir) {
206			gitDir = filepath.Join(root, gitDir)
207		}
208		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
209		if !ok {
210			return false
211		}
212		if !filepath.IsAbs(back) {
213			back = filepath.Join(gitDir, back)
214		}
215		a, errA := filepath.EvalSymlinks(back)
216		b, errB := filepath.EvalSymlinks(dotGit)
217		return errA == nil && errB == nil && a == b
218	}
