331	// renderCharts lints, renders and validates each chart. Without helm, every
332	// chart is reported as not rendered.
333	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
334		tool := v.opts.Helm
335		for _, chart := range charts {
336			if !available(tool) {
337				v.report.Unrendered = append(v.report.Unrendered, chart)
338				continue
339			}
340			// helm reads no remote base, so it never has the network.
341			scope := v.scope.cut()
342			lint := helmLint(ctx, scope, chart, tool)
343			v.report.Findings = append(v.report.Findings, lint...)
344	
345			cmd := helmArgs(scope, chart, tool, "template")
346			log.Printf("Running: %s", cmd.Loggable())
347			rendered, err := runner.Run(ctx, cmd, nil)
348			if err != nil {
349				if ctx.Err() != nil {
350					return ctx.Err()
351				}
352				// helm lint renders the chart too, so a chart that does not
353				// render has usually been reported by it already, with more to
354				// say. The render failure is the fallback, not a second copy.
355				if !hasError(lint) {
356					repro, from := renderRepro(tool, "helm", "template", chart)
357					v.report.Findings = append(v.report.Findings,
358						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", from,
359							renderSteps(SourceHelm, chart, from, failureDetail(err), false), repro, err))
360				}
361				continue
362			}
363			origins := helmOrigins(rendered, chart)
364			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
365				if file, ok := origins[kind+"/"+name]; ok {
366					return file
367				}
368				return chart
369			})
370			if err != nil {
371				return fmt.Errorf("chart %s: %w", chart, err)
372			}
373		}
374		return nil
375	}
376	
377	// renderKustomizations builds and validates each overlay. Without kustomize,
378	// every overlay is reported as not rendered.
379	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
380		tool := v.opts.Kustomize
381		for _, dir := range dirs {
382			if !available(tool) {
383				v.report.Unrendered = append(v.report.Unrendered, dir)
384				continue
385			}
386			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
387			scope := v.scope
388			if !v.opts.AllowRemoteBases {
389				scope = scope.cut()
390			}
391			cmd := kustomizeArgs(scope, dir, tool)
392			log.Printf("Running: %s", cmd.Loggable())
393			rendered, err := runner.Run(ctx, cmd, nil)
394			if err != nil {
395				if ctx.Err() != nil {
396					return ctx.Err()
397				}
398				repro, from := renderRepro(tool, "kustomize", "build", dir)
399				detail := failureDetail(err)
400				blocked := scope.offline && remoteBlocked(detail, from)
401				f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
402					renderSteps(SourceKustomize, dir, from, detail, blocked), repro, err)
403				if blocked {
404					f.Title = remoteBlockedHeadline
405					f.Resolution = remoteBlockedResolution
406					// A copied `kustomize build` would run the refused fetch again, with
407					// the user's ssh agent and proxy, on a repository that is not trusted.
408					f.Repro = ""
409				}
410				v.report.Findings = append(v.report.Findings, f)
411				continue
412			}
413			// kustomize adds no origin to what it emits unless the kustomization
414			// asks for it, and DevDesk does not write into the file to ask. The
415			// overlay is what was built, so it is what a finding points at.
416			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
417			if err != nil {
418				return fmt.Errorf("overlay %s: %w", dir, err)
419			}
420		}
421		return nil
422	}
