424	// validateRendered runs kubeconform over rendered YAML and points each
425	// finding back at the file it came from. A rendered line is not a line of
426	// any file in the repository, so these findings carry none.
427	func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
428		if len(bytes.TrimSpace(rendered)) == 0 {
429			return nil
430		}
431		cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
432		log.Printf("Running: %s", cmd.Loggable())
433		out, err := runner.Run(ctx, cmd, nil)
434		if err := kubeconformFailure(out, err); err != nil {
435			return err
436		}
437		noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
438		findings, skipped, err := parseKubeconformReport(out, v.opts.KubernetesVersion, noFile, origin, dialect)
439		if err != nil {
440			return err
441		}
442		v.report.SkippedCustom += skipped
443		for i := range findings {
444			findings[i].IaCType = dialect
445		}
446		v.report.Findings = append(v.report.Findings, findings...)
447		return nil
448	}
