func typedKustomizeDir(dir string) string {
	first, _, _ := strings.Cut(dir, "/")
	if (first != "." && first != ".." && strings.ContainsAny(first, ".:@")) || strings.HasPrefix(dir, "-") {
		return asPathArg(dir)
	}
